<template><aside class="sidebar"><header><PosIcon name="pill" size="18" /><div><strong>Pharmacy Dispensing</strong><small>Prescription and inventory controls</small></div></header><section><div class="section-title"><span><PosIcon name="clipboard-list" size="14" /> Clinical prescription</span><button @click="showModal = true">Intake</button></div><p v-if="dispensedCount">{{ dispensedCount }} medication(s) in active sale</p><p v-else>No prescription attached to this sale.</p></section><section><div class="section-title"><span><PosIcon name="layers" size="14" /> FEFO allocation</span></div><p>{{ batches.length ? `${batches.length} batches available` : 'No batches available' }}</p></section><section><div class="section-title"><span><PosIcon name="lock" size="14" /> Controlled sign-off</span></div><p>Authorization status is managed by the pharmacy service.</p></section><button class="print" @click="printLabel"><PosIcon name="printer" size="14" /> Print dispensing label</button><div v-if="showModal" class="modal"><div class="dialog"><header><strong>Quick Prescription Intake</strong><button @click="showModal = false"><PosIcon name="x" size="15" /></button></header><label>Patient name<input v-model="form.patient" /></label><label>Medication<select v-model="form.drug"><option v-for="drug in drugs" :key="drug.id" :value="drug">{{ drug.name }}</option></select></label><label>Quantity<input v-model.number="form.quantity" type="number" min="1" /></label><div class="actions"><button @click="showModal = false">Cancel</button><button class="primary" @click="dispense">Add to sale</button></div></div></div></aside></template>
<script setup>
import { onMounted,ref } from 'vue'; import { PosIcon } from '@pos/ui'; import { useApi } from '../../../../apps/pos/src/composables/useApi.js'
const emit=defineEmits(['add-item','notification']); const api=useApi(); const drugs=ref([]); const batches=ref([]); const dispensedCount=ref(0); const showModal=ref(false); const form=ref({patient:'',drug:null,quantity:1}); onMounted(async()=>{try{const [catalog,batchData]=await Promise.all([api.get('/api/v1/pharmacy/catalog'),api.get('/api/v1/pharmacy/batches')]);drugs.value=catalog.items??[];form.value.drug=drugs.value[0]??null;batches.value=batchData.items??[]}catch{emit('notification',{message:'Pharmacy options could not be loaded. Please contact your administrator.',type:'error'})}}); function dispense(){if(!form.value.drug){emit('notification',{message:'Select a medication before adding it',type:'warning'});return}const drug=form.value.drug;const item={id:`rx-${drug.id}`,name:drug.name,sku:drug.sku,price_minor:Number(drug.price_minor)*form.value.quantity,unit_price_minor:Number(drug.price_minor),quantity:1,kind:drug.kind||'stocked',notes:form.value.patient?`Patient: ${form.value.patient}`:''};emit('add-item',item);dispensedCount.value++;showModal.value=false;emit('notification',{message:'Medication added to the active sale',type:'success'})} function printLabel(){window.print()}
</script>
<style scoped>.sidebar{display:flex;flex-direction:column;gap:12px;padding:14px;border:1px solid #bbf7d0;border-radius:10px;background:#f0fdf4}.sidebar header,.section-title,.actions{display:flex;align-items:center;gap:8px}.sidebar header{padding-bottom:8px;border-bottom:1px solid #bbf7d0}.sidebar header small,.sidebar p{display:block;color:#64748b;font-size:11px}.section-title{justify-content:space-between;color:#166534;font-size:11px;font-weight:700}.section-title span{display:flex;align-items:center;gap:5px}.section-title button,.actions button,.print{padding:7px 9px;border:1px solid #cbd5e1;border-radius:6px;background:#fff;color:#334155;font-size:11px;cursor:pointer}.print{display:inline-flex;align-items:center;justify-content:center;gap:5px}.modal{position:fixed;inset:0;display:grid;place-items:center;background:#0005;z-index:10}.dialog{display:flex;flex-direction:column;gap:12px;width:min(420px,90vw);padding:18px;border-radius:10px;background:#fff}.dialog header{justify-content:space-between}.dialog header button{border:0;background:transparent;cursor:pointer}.dialog label{display:flex;flex-direction:column;gap:5px;color:#475569;font-size:11px;font-weight:700}.dialog input,.dialog select{padding:8px;border:1px solid #cbd5e1;border-radius:6px}.actions{justify-content:flex-end}.actions .primary{background:#0284c7;color:#fff;border-color:#0284c7}</style>
